[CmdletBinding()]
param([Parameter(Mandatory)][string]$EvidenceJoinPath,[Parameter(Mandatory)][string]$CapabilityPath,[Parameter(Mandatory)][string]$AdversarialPath,[Parameter(Mandatory)][string]$StrictReceiptPath,[string[]]$RequiredEvidence=@())
$ErrorActionPreference='Stop';function Read-GateJson([string]$p){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "FINAL_GATE_INPUT_MISSING:$p"};Get-Content -Raw -Encoding UTF8 $p|ConvertFrom-Json};$j=Read-GateJson $EvidenceJoinPath;$c=Read-GateJson $CapabilityPath;$a=Read-GateJson $AdversarialPath;$s=Read-GateJson $StrictReceiptPath;$findings=@();if([string]$j.decision -eq 'unverifiable'){$findings+='evidence-join-unverifiable'};if([string]$c.status -ne 'passed' -or [int]$c.receiptCount -ne 6){$findings+='abcd-capability-incomplete'};if([string]$a.status -ne 'passed'){$findings+='adversarial-check-failed'};if([string]$s.status -ne 'passed'){$findings+='strict-receipt-failed'};$runtimeMissing=([string]$j.runtimeStatus -eq 'runtime-not-run');if(-not $runtimeMissing -and @($RequiredEvidence).Count -gt 0){foreach($req in $RequiredEvidence){if($null -eq $j.PSObject.Properties[$req] -or [string]::IsNullOrWhiteSpace([string]$j.$req)){$findings+="required-evidence-missing:$req"}}};$decision=if($findings.Count){'unverifiable'}elseif($runtimeMissing){'partial'}else{'aligned'};[ordered]@{schemaVersion=1;gate='es-game-core-loop-final-gate';decision=$decision;authority='ABCD-final-decision';findings=$findings;requiredEvidence=@($RequiredEvidence);runtimeStatus=if($runtimeMissing){'runtime-not-run'}else{'runtime-passed'};claimsNotProven=if($runtimeMissing){@('Unity Runtime','PlayMode presentation','Profiler/performance','Player/IL2CPP/release')}else{@()}}|ConvertTo-Json -Depth 12
